// VendorUpload is the resolver for the VendorUpload field.
func (r *mutationResolver) VendorUpload(ctx context.Context, files []*graphql.Upload, input model.ProductInput) (*model.Product, error) {
	// Retrieve the service ID from the context
	serviceIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get service ID: %v", err)
	}

	// Parse UUID from string
	serviceID, err := uuid.Parse(*serviceIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid service ID: %w", err)
	}

	// Find the associated service
	var service model.Service
	if err := r.DB.First(&service, "id = ?", serviceID).Error; err != nil {
		return nil, fmt.Errorf("failed to find service: %w", err)
	}

	bucketName := fmt.Sprintf("service-%s-bucket", serviceID)
	// log.Printf("Vendor bucket name: %s", bucketName)

	// Ensure the bucket exists
	if err := helper.CreateBucketInMinio(ctx, r.MinIOClient, bucketName); err != nil {
		return nil, fmt.Errorf("failed to create bucket: %w", err)
	}

	// Ensure files were provided
	if len(files) == 0 {
		return nil, fmt.Errorf("no files uploaded")
	}

	var productURLs []string

	// Upload files to MinIO
	for _, file := range files {
		// log.Printf("Uploading file: %s", file.Filename)

		fileURL, err := helper.UploadFileToMinio(ctx, r.MinIOClient, bucketName, "product", file)
		if err != nil {
			return nil, fmt.Errorf("failed to upload file %s: %v", file.Filename, err)
		}
		productURLs = append(productURLs, fileURL)
	}

	// Process category pointers into a string slice
	var categories []string
	for _, catPtr := range input.Categories {
		if catPtr != nil {
			categories = append(categories, *catPtr)
		}
	}

	var itemsTypes []string
	for _, itemPtr := range input.ItemsType {
		if itemPtr != nil {
			itemsTypes = append(categories, *itemPtr)
		}
	}
	vendorId := service.ID.String()
	// Create and populate product model
	product := model.Product{
		Name:        &input.Name,
		Price:       &input.Price,
		State:       &input.State,
		ImageUrls:   productURLs,
		Categories:  categories,
		Description: input.Description,
		ItemsType: itemsTypes,
		VendorID:    &vendorId,
	}

	// Save the product to DB
	if err := r.DB.Create(&product).Error; err != nil {
		return nil, fmt.Errorf("failed to save product: %w", err)
	}

	return &product, nil
}

