// SendChatMessageByNumber is the resolver for the sendChatMessageByNumber field.
func (r *mutationResolver) SendChatMessageByNumber(ctx context.Context, input model.ChatMessageAdminInput) (*model.ChatMessage, error) {
	// Start a transaction
	tx := r.DB.Begin()
	if tx.Error != nil {
		return nil, fmt.Errorf("failed to start transaction: %v", tx.Error)
	}
	defer func() {
		if r := recover(); r != nil {
			tx.Rollback()
		}
	}()

	// Find the most recent order for this customer
	var latestOrder model.Order
	if err := tx.Where("customer_number = ?", input.CustomerNumber).
		Order("created_at DESC").
		First(&latestOrder).Error; err != nil {
		tx.Rollback()
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("no orders found for customer number: %s", input.CustomerNumber)
		}
		return nil, fmt.Errorf("failed to fetch latest order: %v", err)
	}

	// Validate content
	if strings.TrimSpace(input.Content) == "" {
		tx.Rollback()
		return nil, fmt.Errorf("message content cannot be empty")
	}

	// Create chat message for the latest order
	chatMessage := &model.ChatMessage{
		OrderID: latestOrder.ID.String(),
		Sender:  model.SenderTypeVendor,
		Content: input.Content,
		Read:    false,
	}

	// Save the chat message
	if err := tx.Create(chatMessage).Error; err != nil {
		tx.Rollback()
		return nil, fmt.Errorf("failed to save chat message: %v", err)
	}

	// Commit the transaction
	if err := tx.Commit().Error; err != nil {
		return nil, fmt.Errorf("failed to commit transaction: %v", err)
	}

	// Log successful message creation
	log.Printf("Created chat message for customer %s on order %s",
		input.CustomerNumber, latestOrder.ID.String())

	// Return array with single message to match the expected return type
	return chatMessage, nil
}

// MarkMessagesAsRead is the resolver for the markMessagesAsRead field.
func (r *mutationResolver) MarkMessagesAsRead(ctx context.Context, sender model.SenderType) (bool, error) {
	orderID := "nju"

	// orderID, err := middleware.GetOrderTrackingCookie(r)
	// if err != nil {
	// 	return false, fmt.Errorf("no tracking cookie found: %v", err)
	// }
	//todocookies

	// Parse the order ID
	// parsedOrderID, err := uuid.Parse(orderID)

	// if err != nil {
	// 	return false, fmt.Errorf("invalid order ID: %v", err)
	// }

	// Verify that the order exists
	var order model.Order
	if err := r.DB.Where("id = ?", "parsedOrderID").First(&order).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return false, fmt.Errorf("order not found with ID: %s", orderID)
		}
		return false, fmt.Errorf("failed to fetch order: %v", err)
	}

	// Mark messages as read
	// The logic here is to mark messages as read from the opposite sender
	// If vendor is viewing, mark customer messages as read, and vice versa
	var oppositeSender model.SenderType
	if sender == model.SenderTypeCustomer {
		oppositeSender = model.SenderTypeVendor
	} else {
		oppositeSender = model.SenderTypeCustomer
	}

	// Update messages where order_id matches and sender is the opposite type
	if err := r.DB.Model(&model.ChatMessage{}).
		Where("order_id = ? AND sender = ? AND read = ?", orderID, oppositeSender, false).
		Update("read", true).Error; err != nil {
		return false, fmt.Errorf("failed to mark messages as read: %v", err)
	}

	return true, nil
}

// DeleteAllChatMessageByNumber is the resolver for the deleteAllChatMessageByNumber field.
func (r *mutationResolver) DeleteAllChatMessageByNumber(ctx context.Context, customerNumber string) (bool, error) {
	// Start a transaction
	tx := r.DB.Begin()
	if tx.Error != nil {
		return false, fmt.Errorf("failed to start transaction: %v", tx.Error)
	}
	defer func() {
		if r := recover(); r != nil {
			tx.Rollback()
		}
	}()

	// First get all orders for this customer number
	var orders []*model.Order
	if err := tx.Where("customer_number = ?", customerNumber).
		Find(&orders).Error; err != nil {
		tx.Rollback()
		return false, fmt.Errorf("failed to fetch orders: %v", err)
	}

	if len(orders) == 0 {
		tx.Rollback()
		return false, fmt.Errorf("no orders found for customer number: %s", customerNumber)
	}

	// Collect all order IDs
	var orderIDs []string
	for _, order := range orders {
		orderIDs = append(orderIDs, order.ID.String())
	}

	// Delete all chat messages for these orders
	result := tx.Where("order_id IN ?", orderIDs).
		Delete(&model.ChatMessage{})

	if result.Error != nil {
		tx.Rollback()
		return false, fmt.Errorf("failed to delete chat messages: %v", result.Error)
	}

	// Check if any records were deleted
	if result.RowsAffected == 0 {
		tx.Rollback()
		return false, fmt.Errorf("no chat messages found to delete for customer number: %s", customerNumber)
	}

	// Commit the transaction
	if err := tx.Commit().Error; err != nil {
		return false, fmt.Errorf("failed to commit transaction: %v", err)
	}

	// Log successful deletion
	log.Printf("Deleted %d chat messages for customer %s", result.RowsAffected, customerNumber)

	return true, nil
}

// RequestItem is the resolver for the requestItem field.
func (r *mutationResolver) RequestItem(ctx context.Context, input model.RequestInput) (*model.RequestItem, error) {
	// Generate a bucket name for storing images
	timestamp := time.Now().UnixNano() / 1000000 // milliseconds

	var simpleName string
	if input.Name != nil {
		simpleName = strings.ToLower(strings.ReplaceAll(*input.Name, " ", "-"))
		simpleName = regexp.MustCompile(`[^a-z0-9-]`).ReplaceAllString(simpleName, "")
	} else {
		simpleName = "request"
	}

	bucketName := fmt.Sprintf("req-%s-%d", simpleName[:helper.MinInt(len(simpleName), 10)], timestamp)

	log.Printf("Creating request item bucket: %s", bucketName)

	// Ensure the bucket exists in MinIO
	if err := helper.CreateBucketInMinio(ctx, r.MinIOClient, bucketName); err != nil {
		return nil, err
	}

	var imageURLs []string

	// Upload each image and store the URL
	if input.Images != nil {
		for _, file := range input.Images {
			fileURL, err := helper.UploadFileToMinio(ctx, r.MinIOClient, bucketName, "request", file)
			if err != nil {
				return nil, fmt.Errorf("failed to upload file %s: %v", file.Filename, err)
			}
			imageURLs = append(imageURLs, fileURL)
		}
	}

	// Set default state for new request items
	initialState := "PENDING"

	// Optional category handling
	var category string
	if input.Category != nil {
		category = *input.Category
	}

	// Create a new request item
	requestItem := model.RequestItem{
		Name:        input.Name,
		Price:       input.Price,
		State:       (*model.ProductState)(&initialState),
		Categories:  &category,
		ImageUrls:   imageURLs,
		Description: input.Description,
	}

	// Save the request item to the database
	if err := r.DB.Create(&requestItem).Error; err != nil {
		return nil, fmt.Errorf("failed to save request item: %v", err)
	}

	return &requestItem, nil
}

